INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-amethyst', 4, 'published', 'gel', 'Amethyst', '#6B2FC0', '{"bg":"#1B0B30","bg2":"#090312","surface":"#5B21A8","accent":"#B98CFF","glow":"#8A3FF0"}', 'assets/img/gel-amethyst.webp?v=3', 'assets/img/gel-amethyst-atmo.webp', '[{"src":"assets/img/gel-amethyst-studio.webp?v=2","cap":{"uz":"1 litrli shisha, 22 marta yuvishga","ru":"Литровый флакон на 22 стирки","en":"A 1 litre bottle for 22 washes","ar":"عبوة لتر واحد تكفي 22 غسلة"}},{"src":"assets/img/gel-amethyst-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/gel-room.webp?v=2","cap":{"uz":"Uchala ifor: Amethyst, Crystal Bloom, Original","ru":"Все три аромата: Amethyst, Crystal Bloom, Original","en":"All three scents: Amethyst, Crystal Bloom, Original","ar":"العطور الثلاثة: Amethyst وCrystal Bloom وOriginal"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Qadoq dizayni: 1000 ml, 22 yuvish","ru":"Дизайн упаковки: 1000 мл, 22 стирки","en":"Pack design: 1000 ml, 22 washes","ar":"تصميم العبوة: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Ametist va lavanda","line":"Amethyst ifori, endi suyuq gelda","hook":"Kir oz bo‘lsa, ozroq quyasiz.","desc":"Amethyst iforli suyuq gel. Hidi iliq, lavandani eslatadi va kiyimda kechgacha seziladi. Gel qiyin dog‘ va hidni ketkazadi, sovuq suvda ham yuvadi. Qancha quyishni o‘zingiz hal qilasiz.","for":"Kirni tez-tez, oz-ozdan yuvadiganlarga. Iliq va sezilarli hidni yoqtirsangiz, shuni oling."},"ru":{"scent":"Аметист и лаванда","line":"Аромат Amethyst, теперь в жидком геле","hook":"Белья немного? Налейте меньше.","desc":"Жидкий гель с ароматом Amethyst. Запах тёплый, напоминает лаванду и чувствуется на одежде до вечера. Гель убирает сложные пятна и запахи, стирает и в холодной воде. Сколько наливать, решаете сами.","for":"Тем, кто стирает часто и понемногу. Если вам нравится тёплый и заметный запах, берите этот."},"en":{"scent":"Amethyst and lavender","line":"Amethyst scent, now in a liquid gel","hook":"Not much washing? Pour a little less.","desc":"Liquid gel with the Amethyst scent. It’s warm, a bit like lavender, and you can still smell it on your clothes in the evening. The gel gets out tough stains and odours and works in cold water too. You decide how much to pour.","for":"For people who wash often, a little at a time. If you like a warm scent you can actually notice, this is the one."},"ar":{"scent":"الجمشت واللافندر","line":"عطر Amethyst في جل سائل","hook":"غسيل قليل؟ اسكب أقل.","desc":"جل سائل بعطر Amethyst. رائحته دافئة تذكّر باللافندر، وتبقى على الملابس حتى المساء. يزيل البقع الصعبة والروائح، ويغسل جيدًا حتى بالماء البارد. وأنت تقرر كم تسكب منه.","for":"لمن يغسل كثيرًا وبكميات صغيرة. إذا كنت تحب رائحة دافئة وواضحة، فهذا اختيارك."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-crystal', 5, 'published', 'gel', 'Crystal Bloom', '#1F55D0', '{"bg":"#06173F","bg2":"#020818","surface":"#1846C0","accent":"#79B8FF","glow":"#2A6CF0"}', 'assets/img/gel-crystal.webp?v=3', 'assets/img/gel-crystal-atmo.webp', '[{"src":"assets/img/gel-crystal-studio.webp?v=2","cap":{"uz":"1 litrli shisha, 22 marta yuvishga","ru":"Литровый флакон на 22 стирки","en":"A 1 litre bottle for 22 washes","ar":"عبوة لتر واحد تكفي 22 غسلة"}},{"src":"assets/img/gel-crystal-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/gel-room.webp?v=2","cap":{"uz":"Uchala ifor: Amethyst, Crystal Bloom, Original","ru":"Все три аромата: Amethyst, Crystal Bloom, Original","en":"All three scents: Amethyst, Crystal Bloom, Original","ar":"العطور الثلاثة: Amethyst وCrystal Bloom وOriginal"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Qadoq dizayni: 1000 ml, 22 yuvish","ru":"Дизайн упаковки: 1000 мл, 22 стирки","en":"Pack design: 1000 ml, 22 washes","ar":"تصميم العبوة: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Gul barglari","line":"Yengil gul hidi, suyuq gelda","hook":"Rangli kiyim uchun yengil gul hidi.","desc":"Crystal Bloom iforli suyuq gel. Hidi yengil, gulga o‘xshaydi, dimoqqa urmaydi. Dog‘ va hidni ketkazadi, rangli kiyimning rangini asraydi. Sovuq suvda ham yuvadi.","for":"Rangli kiyimni ko‘p yuvadiganlarga: ko‘ylak, futbolka, yozgi yengil kiyimlar."},"ru":{"scent":"Цветочные лепестки","line":"Лёгкий цветочный запах в жидком геле","hook":"Лёгкий цветочный запах для цветных вещей.","desc":"Жидкий гель с ароматом Crystal Bloom. Запах лёгкий, цветочный, в нос не бьёт. Гель убирает пятна и запахи, цветные вещи не теряют цвет. Стирает и в холодной воде.","for":"Тем, кто часто стирает цветное: рубашки, футболки, лёгкую летнюю одежду."},"en":{"scent":"Flower petals","line":"A light floral scent in a liquid gel","hook":"A light floral scent for colours.","desc":"Liquid gel with the Crystal Bloom scent. It’s light and flowery and doesn’t overpower. It removes stains and smells and helps coloured clothes keep their colour. Works in cold water too.","for":"For people who wash a lot of colours: shirts, T-shirts, light summer clothes."},"ar":{"scent":"بتلات الزهور","line":"عطر زهري خفيف في جل سائل","hook":"رائحة زهور خفيفة للملابس الملونة.","desc":"جل سائل بعطر Crystal Bloom. رائحته خفيفة تشبه الزهور، وليست نفّاذة. يزيل البقع والروائح، ويحافظ على لون الملابس الملونة. ويغسل جيدًا حتى بالماء البارد.","for":"لمن يغسل الملابس الملونة كثيرًا: القمصان، والتيشيرتات، وملابس الصيف الخفيفة."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('gel-original', 6, 'published', 'gel', 'Original', '#1F8040', '{"bg":"#05261A","bg2":"#01110A","surface":"#18733A","accent":"#9BE58A","glow":"#2DB352"}', 'assets/img/gel-original.webp?v=3', 'assets/img/gel-original-atmo.webp', '[{"src":"assets/img/gel-original-studio.webp?v=2","cap":{"uz":"1 litrli shisha, 22 marta yuvishga","ru":"Литровый флакон на 22 стирки","en":"A 1 litre bottle for 22 washes","ar":"عبوة لتر واحد تكفي 22 غسلة"}},{"src":"assets/img/gel-original-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/gel-room.webp?v=2","cap":{"uz":"Uchala ifor: Amethyst, Crystal Bloom, Original","ru":"Все три аромата: Amethyst, Crystal Bloom, Original","en":"All three scents: Amethyst, Crystal Bloom, Original","ar":"العطور الثلاثة: Amethyst وCrystal Bloom وOriginal"}},{"src":"assets/img/gel-photo.jpg","cap":{"uz":"Qadoq dizayni: 1000 ml, 22 yuvish","ru":"Дизайн упаковки: 1000 мл, 22 стирки","en":"Pack design: 1000 ml, 22 washes","ar":"تصميم العبوة: 1000 مل، 22 غسلة"}}]', '{"uz":{"scent":"Yashil yaproqlar","line":"Tetik, klassik hid, suyuq gelda","hook":"Oddiy, tetik hid, uydagilarning hammasiga yoqadi.","desc":"Original iforli suyuq gel. Hidi yashil yaproqlarni eslatadi, tetik va oddiy. Qiyin dog‘ni yaxshi ketkazadi, sovuq suvda va qisqa dasturda ham ishlaydi.","for":"Oila kirini yuvadiganlarga: choyshab, sochiq, ish kiyimi."},"ru":{"scent":"Зелёные листья","line":"Свежая классика в жидком геле","hook":"Простой свежий запах, нравится всей семье.","desc":"Жидкий гель с ароматом Original. Запах напоминает зелёные листья, свежий и простой. Гель хорошо отстирывает сложные пятна, работает и в холодной воде, и на короткой программе.","for":"Тем, кто стирает на всю семью: постельное бельё, полотенца, рабочую одежду."},"en":{"scent":"Green leaves","line":"Fresh classic scent, as a gel","hook":"Simple and fresh. Everyone at home likes it.","desc":"Liquid gel with the Original scent. It smells of green leaves, fresh and simple. It’s good at getting out tough stains and works in cold water and on short cycles.","for":"For doing the family wash: bed linen, towels, work clothes."},"ar":{"scent":"أوراق خضراء","line":"عطر كلاسيكي منعش في جل سائل","hook":"رائحة بسيطة ومنعشة تعجب كل من في البيت.","desc":"جل سائل بعطر Original. رائحته تذكّر بالأوراق الخضراء، منعشة وبسيطة. يزيل البقع الصعبة جيدًا، ويعمل في الماء البارد وفي البرامج القصيرة أيضًا.","for":"لمن يغسل ملابس العائلة: الشراشف والمناشف وملابس العمل."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('powder-ocean', 7, 'published', 'powder', 'Ocean Fresh', '#0E6FD0', '{"bg":"#04234A","bg2":"#010D1E","surface":"#0E66C2","accent":"#6FD6FF","glow":"#1C9BF0"}', 'assets/img/powder-ocean.webp?v=3', 'assets/img/powder-ocean-atmo.webp', '[{"src":"assets/img/powder-ocean-studio.webp?v=2","cap":{"uz":"10 kilolik qop","ru":"Мешок на 10 кг","en":"The 10 kg bag","ar":"كيس 10 كغ"}},{"src":"assets/img/powder-ocean-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/powder-room.webp?v=2","cap":{"uz":"Ocean Fresh va Purple Splash","ru":"Ocean Fresh и Purple Splash","en":"Ocean Fresh and Purple Splash","ar":"Ocean Fresh وPurple Splash"}},{"src":"assets/img/powder-photo.jpg","cap":{"uz":"Qadoq dizayni: Max Power, 10 kg","ru":"Дизайн упаковки: Max Power, 10 кг","en":"Pack design: Max Power, 10 kg","ar":"تصميم الكيس: Max Power ‏10 كغ"}}]', '{"uz":{"scent":"Dengiz shabadasi va oq gullar","line":"Salqin, dengizni eslatadigan hid","hook":"Ochiq havoda quritilgandek salqin hid.","desc":"Ocean Fresh hidi salqin, dengiz shabadasini eslatadi, orasida oq gullar ham seziladi. Kukun qiyin dog‘ va hidni ketkazadi, sovuq suvda ham yuvadi. 10 kilolik qop katta oilaga ham ancha vaqtga yetadi.","for":"Kir ko‘p chiqadigan uylarga: choyshab, sochiq, maktab formasi, sport kiyimi."},"ru":{"scent":"Морской бриз и белые цветы","line":"Прохладный морской запах","hook":"Прохладный запах белья с улицы.","desc":"У Ocean Fresh прохладный запах, похожий на морской бриз, и в нём чувствуются белые цветы. Порошок убирает сложные пятна и запахи, стирает и в холодной воде. Мешка на 10 кг даже большой семье хватает надолго.","for":"Для дома, где много стирки: постельное бельё, полотенца, школьная форма, спортивная одежда."},"en":{"scent":"Sea breeze and white flowers","line":"A cool, seaside smell","hook":"Like it dried in the fresh air.","desc":"Ocean Fresh smells cool, like a sea breeze, with a hint of white flowers. The powder gets out tough stains and smells and works in cold water too. A 10 kg bag lasts even a big family quite a while.","for":"For homes with lots of washing: bed linen, towels, school uniforms, sports kit."},"ar":{"scent":"نسيم البحر وزهور بيضاء","line":"رائحة بحرية منعشة","hook":"كأنها جفت في الهواء الطلق.","desc":"رائحة Ocean Fresh منعشة تذكّر بنسيم البحر، وفيها لمسة من الزهور البيضاء. المسحوق يزيل البقع الصعبة والروائح، ويغسل جيدًا حتى بالماء البارد. وكيس 10 كغ يكفي حتى العائلة الكبيرة وقتًا طويلًا.","for":"للبيوت التي يكثر فيها الغسيل: الشراشف والمناشف والزي المدرسي والملابس الرياضية."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('powder-purple', 8, 'published', 'powder', 'Purple Splash', '#9A2FC8', '{"bg":"#2A0A3D","bg2":"#110318","surface":"#8E2DBF","accent":"#E79BFF","glow":"#B847E8"}', 'assets/img/powder-purple.webp?v=3', 'assets/img/powder-purple-atmo.webp', '[{"src":"assets/img/powder-purple-studio.webp?v=2","cap":{"uz":"10 kilolik qop","ru":"Мешок на 10 кг","en":"The 10 kg bag","ar":"كيس 10 كغ"}},{"src":"assets/img/powder-purple-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/powder-room.webp?v=2","cap":{"uz":"Ocean Fresh va Purple Splash","ru":"Ocean Fresh и Purple Splash","en":"Ocean Fresh and Purple Splash","ar":"Ocean Fresh وPurple Splash"}},{"src":"assets/img/powder-photo.jpg","cap":{"uz":"Qadoq dizayni: Max Power, 10 kg","ru":"Дизайн упаковки: Max Power, 10 кг","en":"Pack design: Max Power, 10 kg","ar":"تصميم الكيس: Max Power ‏10 كغ"}}]', '{"uz":{"scent":"Binafsha gullar","line":"To‘q, gulli hid","hook":"Kiyimdan gul hidi kelib turadi.","desc":"Ocean Fresh salqinroq bo‘lsa, Purple Splash gulliroq: hidi binafsha gullarga o‘xshaydi. Kukun dog‘ va hidni ketkazadi, sovuq suvda va qisqa dasturda ham yuvadi. Hidi kiyimda uzoq qoladi.","for":"Gulli hidni yoqtiradiganlarga: kundalik kiyim, parda, dasturxon, sport kiyimi."},"ru":{"scent":"Фиолетовые цветы","line":"Насыщенный цветочный запах","hook":"От одежды пахнет цветами.","desc":"Ocean Fresh прохладнее, а Purple Splash более цветочный: запах похож на фиолетовые цветы. Порошок убирает пятна и запахи, стирает и в холодной воде, и на короткой программе. Запах долго держится на одежде.","for":"Тем, кто любит цветочные запахи. Для повседневной одежды, штор, скатертей и спортивной формы."},"en":{"scent":"Violet flowers","line":"A rich floral scent","hook":"Your clothes smell of flowers.","desc":"Ocean Fresh is the cooler one. Purple Splash is more flowery and smells like violets. The powder removes stains and smells and works in cold water and on short cycles. The scent stays on your clothes for a long time.","for":"For people who like a floral scent: everyday clothes, curtains, tablecloths, sports kit."},"ar":{"scent":"زهور بنفسجية","line":"رائحة زهور غنية","hook":"ملابس برائحة الزهور.","desc":"إذا كان Ocean Fresh أكثر انتعاشًا، فإن Purple Splash أقرب إلى الزهور: رائحته تشبه الزهور البنفسجية. المسحوق يزيل البقع والروائح، ويغسل حتى بالماء البارد وفي البرامج القصيرة. ورائحته تبقى على الملابس طويلًا.","for":"لمن يحب الروائح الزهرية: ملابس كل يوم، والستائر، ومفارش المائدة، والملابس الرياضية."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('oxi', 9, 'published', 'oxi', 'OXI Power', '#E9D8B4', '{"bg":"#0D1B33","bg2":"#050B16","surface":"#1E3A66","accent":"#E9C98E","glow":"#3F6FB0"}', 'assets/img/oxi.webp?v=3', 'assets/img/oxi-atmo.webp', '[{"src":"assets/img/oxi-photo-front.webp","cap":{"uz":"Haqiqiy surat: old tomoni, 15 kapsula","ru":"Настоящее фото: лицевая сторона, 15 капсул","en":"Real photo: the front, 15 pods","ar":"صورة حقيقية: الواجهة، 15 كبسولة"}},{"src":"assets/img/oxi-photo-back-1.webp","cap":{"uz":"Orqa tomoni: qanday ishlatish va qancha solish","ru":"Обратная сторона: как пользоваться и сколько класть","en":"The back: how to use it and how much to add","ar":"الجهة الخلفية: طريقة الاستخدام والكمية"}},{"src":"assets/img/oxi-photo-back-2.webp","cap":{"uz":"Orqa tomoni: qanday ishlatish va qancha solish","ru":"Обратная сторона: как пользоваться и сколько класть","en":"The back: how to use it and how much to add","ar":"الجهة الخلفية: طريقة الاستخدام والكمية"}},{"src":"assets/img/oxi-photo-back-3.webp","cap":{"uz":"30 kapsulali qadoqning orqasi","ru":"Обратная сторона упаковки на 30 капсул","en":"Back of the 30-pod pack","ar":"الجهة الخلفية لعبوة 30 كبسولة"}},{"src":"assets/img/oxi-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/oxi-studio.webp?v=2","cap":{"uz":"Ichida faol kislorod bor","ru":"Внутри активный кислород","en":"There’s active oxygen inside","ar":"بداخلها أكسجين نشط"}},{"src":"assets/img/oxi-room.webp?v=2","cap":{"uz":"Oq kiyimga ham, rangli kiyimga ham","ru":"И для белого, и для цветного","en":"For both whites and colours","ar":"للملابس البيضاء والملونة"}}]', '{"uz":{"scent":"Oq va rangli kiyim uchun","line":"Qiyin dog‘lar uchun kislorodli kapsula","hook":"Oq ko‘ylakni tashlab yuborishga shoshilmang.","desc":"OXI Power’ni mashinada yuvganda qo‘shasiz yoki dog‘li kiyimni u bilan ivitib qo‘yasiz. Kapsuladagi faol kislorod qiyin dog‘ni ko‘taradi, oq kiyimni oqartiradi. Xlor yo‘q, shuning uchun rangli kiyimga ham bo‘ladi. Issiq suvda (60–90 °C) eng yaxshi ishlaydi.","for":"Oq ko‘ylak, choyshab, sochiq, parda va gilamdagi qiyin dog‘lar uchun. Qadoqda yozilganidek, rakovina va idishlarni tozalashda ham ishlatsa bo‘ladi."},"ru":{"scent":"Для белого и цветного","line":"Капсула от сложных пятен","hook":"Не спешите выбрасывать белую рубашку.","desc":"OXI Power добавляют в машину при стирке или замачивают в нём вещь с пятном. Активный кислород в капсуле выводит сложные пятна и отбеливает белое. Хлора нет, поэтому подходит и для цветных вещей. Лучше всего работает в горячей воде (60–90 °C).","for":"Для сложных пятен на белых рубашках, постельном белье, полотенцах, шторах и коврах. Как написано на упаковке, им можно чистить раковину и посуду."},"en":{"scent":"For whites and colours","line":"Oxygen pods for tough stains","hook":"Don’t throw out that white shirt just yet.","desc":"Add OXI Power to a machine wash, or use it to soak stained clothes. The active oxygen in the pod lifts tough stains and brightens whites. There’s no chlorine, so it’s fine for coloured clothes too. It works best in hot water (60–90 °C).","for":"For tough stains on white shirts, bed linen, towels, curtains and carpets. As it says on the pack, you can also use it to clean sinks and dishes."},"ar":{"scent":"للملابس البيضاء والملونة","line":"كبسولة أكسجين للبقع الصعبة","hook":"لا ترمِ القميص الأبيض بعد.","desc":"تضيف OXI Power إلى الغسالة مع الغسيل، أو تستخدمه لنقع الملابس المبقّعة. الأكسجين النشط في الكبسولة يرفع البقع الصعبة ويبيّض الملابس البيضاء. لا يحتوي على الكلور، لذلك يناسب الملابس الملونة أيضًا. وأفضل نتيجة له في الماء الساخن (60–90 °م).","for":"للبقع الصعبة على القمصان البيضاء والشراشف والمناشف والستائر والسجاد. ويمكن استخدامه أيضًا لتنظيف المغاسل والأواني، كما هو مكتوب على العبوة."}}', 1793273315768, 1793273315768);
INSERT OR IGNORE INTO products (id, sort, status, line, name, color, theme, pack, atmo, gallery, i18n, created_at, updated_at) VALUES ('booster', 10, 'published', 'booster', 'Endless Scent', '#9B4FB5', '{"bg":"#2B0F33","bg2":"#120515","surface":"#8A3E9E","accent":"#F0B6F0","glow":"#C764D8"}', 'assets/img/booster.webp?v=3', 'assets/img/booster-atmo.webp', '[{"src":"assets/img/booster-studio.webp?v=2","cap":{"uz":"Bir qoshig‘i bitta yuvishga","ru":"Одна ложка на одну стирку","en":"One scoop per wash","ar":"مغرفة واحدة لكل غسلة"}},{"src":"assets/img/booster-shot.webp","cap":{"uz":"Qadoq yaqindan","ru":"Упаковка крупным планом","en":"The pack up close","ar":"العبوة عن قرب"}},{"src":"assets/img/booster-room.webp?v=2","cap":{"uz":"Choyshab va sochiq uchun ham","ru":"И для постельного белья, и для полотенец","en":"Good for bed linen and towels too","ar":"وللشراشف والمناشف أيضًا"}},{"src":"assets/img/booster-photo.jpg","cap":{"uz":"6 xil ifor, 3 xil hajm","ru":"6 ароматов и 3 размера упаковки","en":"6 scents, 3 sizes","ar":"6 عطور و3 أحجام"}}]', '{"uz":{"scent":"Amethyst va yana 5 ta ifor","line":"Kiyimni haftalab xushbo‘y qiladi","hook":"Shkafdagi kiyim ham yangi yuvilgandek hid beradi.","desc":"Endless Scent mayda xushbo‘y granulalar. Ularni kukun yoki gel bilan birga barabanga solasiz, yuvish paytida eriydi. Kiyimdan haftalab yoqimli hid keladi, dimiqqan hid qolmaydi. Iforlari: Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony va Ocean Breeze.","for":"Kiyimidan doim yoqimli hid kelishini xohlaydiganlarga. Choyshab, sochiq va sport kiyimi uchun ayniqsa yaxshi. Har qanday kukun, gel yoki kapsula bilan ishlatsa bo‘ladi."},"ru":{"scent":"Amethyst и ещё 5 ароматов","line":"Одежда приятно пахнет неделями","hook":"Вещи в шкафу пахнут, будто только постирали.","desc":"Endless Scent выпускают в виде мелких ароматных гранул. Их насыпают в барабан вместе с порошком или гелем, и во время стирки они растворяются. Одежда приятно пахнет неделями, затхлого запаха не остаётся. Ароматы: Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony и Ocean Breeze.","for":"Тем, кто хочет, чтобы от одежды всегда приятно пахло. Особенно хорош для постельного белья, полотенец и спортивной формы. Можно добавлять к любому порошку, гелю или капсулам."},"en":{"scent":"Amethyst and 5 more scents","line":"Clothes smell nice for weeks","hook":"Even clothes in the wardrobe smell freshly washed.","desc":"Endless Scent comes as small scented granules. You put them in the drum along with your powder or gel, and they dissolve during the wash. Your clothes smell nice for weeks, with no musty smell left. The scents are Amethyst, Crystal Bloom, Original, Rose Blush, Golden Harmony and Ocean Breeze.","for":"For people who want their clothes to always smell nice. Especially good for bed linen, towels and sports kit. You can use it with any powder, gel or pods."},"ar":{"scent":"Amethyst و5 عطور أخرى","line":"ملابس معطرة لأسابيع","hook":"ملابس الخزانة رائحتها كأنها غُسلت للتو.","desc":"Endless Scent حبيبات صغيرة معطرة. تضعها في حوض الغسالة مع المسحوق أو الجل، فتذوب أثناء الغسيل. تفوح من الملابس رائحة طيبة لأسابيع، وتختفي رائحة الرطوبة. العطور المتوفرة: Amethyst وCrystal Bloom وOriginal وRose Blush وGolden Harmony وOcean Breeze.","for":"لمن يريد أن تكون رائحة ملابسه طيبة دائمًا. مناسبة بشكل خاص للشراشف والمناشف والملابس الرياضية. ويمكن استخدامها مع أي مسحوق أو جل أو كبسولات."}}', 1793273315768, 1793273315768);
